package com.bank.qa.contract;

import java.util.*;

// Provider: returns the balance response. Its shape may change over time.
class AccountsProvider {
    private final boolean breakingChange;
    AccountsProvider(boolean breakingChange) { this.breakingChange = breakingChange; }

    Map<String, Object> getBalance(String accountId) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("accountId", accountId);          // string
        if (breakingChange) {
            // BREAKING: renamed 'balance' -> 'amount' and made it a string
            body.put("amount", "950000.00");
        } else {
            body.put("balance", 950000.00);        // number (what consumer expects)
        }
        body.put("currency", "INR");
        return body;
    }
}
