package com.bank.qa.contract;

import java.util.*;
import java.util.logging.Logger;

// Verifies the provider's actual response satisfies the consumer's contract.
class ContractVerifier {
    private static final Logger log = Logger.getLogger(ContractVerifier.class.getName());

    boolean verify(Contract contract, Map<String, Object> actual) {
        boolean ok = true;
        for (Map.Entry<String, String> e : contract.expected.entrySet()) {
            String field = e.getKey(), expectedType = e.getValue();
            if (!actual.containsKey(field)) {
                log.severe("CONTRACT VIOLATION: missing field '" + field + "'");
                ok = false; continue;
            }
            String actualType = (actual.get(field) instanceof Number) ? "number" : "string";
            if (!actualType.equals(expectedType)) {
                log.severe("CONTRACT VIOLATION: field '" + field + "' expected " + expectedType
                    + " but was " + actualType);
                ok = false;
            }
        }
        return ok;
    }
}
