package com.bank.qa.contract;

import java.util.logging.*;

public class ContractDemo {
    private static final Logger log = Logger.getLogger(ContractDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new CtLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // CONSUMER (mobile app) declares what it expects — the contract.
        Contract contract = new Contract()
            .require("accountId", "string")
            .require("balance", "number")     // relies on 'balance' being numeric
            .require("currency", "string");

        ContractVerifier verifier = new ContractVerifier();

        log.info("=== Provider verification: compatible version ===");
        boolean okCompatible = verifier.verify(contract, new AccountsProvider(false).getBalance("SAV2001"));
        log.info("Contract satisfied -> " + (okCompatible ? "PASS (safe to deploy)" : "FAIL"));

        log.info("=== Provider verification: BREAKING change (renamed/retyped) ===");
        boolean okBreaking = verifier.verify(contract, new AccountsProvider(true).getBalance("SAV2001"));
        log.info("Contract satisfied -> " + (okBreaking ? "PASS" : "FAIL (blocked BEFORE deploy)"));

        log.info("Real tooling: Pact — consumer generates pact file, provider verifies, "
            + "Pact Broker + can-I-deploy gates the pipeline.");
    }
}

